import type { TestDefinition } from "./types";
import { FLAT_PROFILE_THRESHOLD } from "./tests/score-utils";
import { spectrumBandIndex } from "./result-art-spectrum";

/**
 * Result art for the illustrated quizzes.
 *
 * Two shapes, matching the two scoring modes that produce a single named
 * result. Both resolve to a processed webp under /results (generated by
 * scripts/process-result-art.mjs from the gitignored repo-root images/
 * sources).
 *
 * - scoreMode "type" quizzes map the winning axis key, plus a balanced
 *   image for the flat-profile result (RESULT_ART).
 * - scoreMode "spectrum" quizzes map one image per band, positionally
 *   against test.spectrumBands (SPECTRUM_ART).
 *
 * - kind "icon": 800x800 square, rendered as a rounded result icon.
 * - kind "bg":   1600x900, rendered as a hero banner behind/above the
 *   type label.
 *
 * Tests without an entry here simply render the results page exactly as
 * before, because art is purely additive.
 */

export type ResultArtKind = "icon" | "bg";

export interface ResultArt {
  kind: ResultArtKind;
  src: string;
  alt: string;
}

interface ArtEntry {
  src: string;
  alt: string;
}

interface TestArtSet {
  kind: ResultArtKind;
  /** Shown when no single axis clearly leads (the quiz's balanced result). */
  balanced: ArtEntry;
  byAxis: Record<string, ArtEntry>;
}

interface SpectrumArtSet {
  kind: ResultArtKind;
  /**
   * One entry per test.spectrumBands entry, in the same order (lowest band
   * first). A length mismatch resolves to no art rather than the wrong art.
   */
  byBand: ArtEntry[];
}

