/**
 * Pick the winning axis the same way scoreTypology does (deviation above the
 * respondent's own mean, with the flat-profile / near-tie guard), so the art
 * always matches the type label the person was actually shown.
 */
function winningAxis(
  axisKeys: string[],
  scores: Record<string, number>
): string | null {
  const values = axisKeys.map((k) => scores[k]);
  if (values.some((v) => typeof v !== "number" || Number.isNaN(v))) return null;

  const mean = values.reduce((a, b) => a + b, 0) / (values.length || 1);
  let bestKey: string | null = null;
  let bestDev = -Infinity;
  let secondDev = -Infinity;
  for (const k of axisKeys) {
    const dev = scores[k] - mean;
    if (dev > bestDev) {
      secondDev = bestDev;
      bestDev = dev;
      bestKey = k;
    } else if (dev > secondDev) {
      secondDev = dev;
    }
  }

  const leadsClearly =
    bestDev >= FLAT_PROFILE_THRESHOLD && bestDev - secondDev >= 2;
  return leadsClearly ? bestKey : null;
}

/**
 * One representative image per test, for surfaces that show a quiz before any
 * result exists (social cards, listings). Axis-keyed quizzes use their balanced
 * art; spectrum quizzes use a middle band. Returns a public path, or null when
 * the test has no art at all.
 *
 * Deriving this from the same tables the results page uses is deliberate: a
 * hand-kept second list silently goes stale every time art is added.
 */
export function getShowcaseArtSrc(slug: string): string | null {
  const typed = RESULT_ART[slug];
  if (typed) return typed.balanced.src;
  const spectrum = SPECTRUM_ART[slug];
  if (spectrum && spectrum.byBand.length > 0) {
    const middle = Math.floor((spectrum.byBand.length - 1) / 2);
    return spectrum.byBand[middle]?.src ?? null;
  }
  return null;
}

/**
 * Art for a decoded result, or null when the test has none (callers must
 * degrade to the art-less layout).
 *
 * `shownLabel` is the result label currently on the page. Spectrum quizzes
 * use it to guarantee the art belongs to the band the reader is being told
 * they landed in; axis-keyed quizzes ignore it.
 */
export function getResultArt(
  test: TestDefinition,
  scores: Record<string, number>,
  shownLabel?: string
): ResultArt | null {
  const spectrum = SPECTRUM_ART[test.slug];
  if (spectrum) {
    if (test.scoreMode !== "spectrum") return null;
    const band = spectrumBandIndex(test, scores, shownLabel);
    if (band === null) return null;
    const entry = spectrum.byBand[band];
    if (!entry) return null;
    return { kind: spectrum.kind, src: entry.src, alt: entry.alt };
  }

  const set = RESULT_ART[test.slug];
  if (!set) return null;

  const winner = winningAxis(Object.keys(set.byAxis), scores);
  const entry = winner ? set.byAxis[winner] ?? set.balanced : set.balanced;
  return { kind: set.kind, src: entry.src, alt: entry.alt };
}
